class Solution { public:
 int minFlips(vector<vector<int>>& g) {int m=g.size(),n=g[0].size(),ans=0;
 for(int i=0;i<m/2;++i)for(int j=0;j<n/2;++j){int s=g[i][j]+g[m-1-i][j]+g[i][n-1-j]+g[m-1-i][n-1-j];ans+=min(s,4-s);}
 int mism=0,ones=0;
 if(m%2)for(int j=0;j<n/2;++j){int a=g[m/2][j],b=g[m/2][n-1-j];mism+=a!=b;ones+=a==b && a==1?2:0;}
 if(n%2)for(int i=0;i<m/2;++i){int a=g[i][n/2],b=g[m-1-i][n/2];mism+=a!=b;ones+=a==b && a==1?2:0;}
 ans+=mism;
 if(mism==0 && ones%4)ans+=2;
 if(m%2 && n%2)ans+=g[m/2][n/2];return ans;
 }
};
